/**
 * Database Transaction Safety Tests
 *
 * Tests for Sub-phase 0.8: atomic transactions, migration runner,
 * WAL management, integrity checks, and the withTransaction helper.
 */

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import Database from "better-sqlite3";
import fs from "fs";
import path from "path";
import os from "os";
import { createDatabase } from "../state/database.js";
import { withTransaction, checkpointWAL } from "../state/database.js";
import type { AutomatonDatabase, AgentTurn, ToolCallResult } from "../types.js";

function makeTmpDbPath(): string {
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "automaton-txn-test-"));
  return path.join(tmpDir, "test.db");
}

describe("Database Transaction Safety", () => {
  let dbPath: string;
  let db: AutomatonDatabase;

  beforeEach(() => {
    dbPath = makeTmpDbPath();
    db = createDatabase(dbPath);
  });

  afterEach(() => {
    try { db.close(); } catch { /* already closed */ }
  });

  // ─── withTransaction helper ──────────────────────────────────

  describe("withTransaction", () => {
    it("wraps operations atomically — both succeed", () => {
      const rawDb = new Database(dbPath);
      withTransaction(rawDb, () => {
        rawDb.prepare("INSERT INTO kv (key, value, updated_at) VALUES (?, ?, datetime('now'))").run("a", "1");
        rawDb.prepare("INSERT INTO kv (key, value, updated_at) VALUES (?, ?, datetime('now'))").run("b", "2");
      });
      const a = rawDb.prepare("SELECT value FROM kv WHERE key = ?").get("a") as { value: string } | undefined;
      const b = rawDb.prepare("SELECT value FROM kv WHERE key = ?").get("b") as { value: string } | undefined;
      expect(a?.value).toBe("1");
      expect(b?.value).toBe("2");
      rawDb.close();
    });

    it("rolls back all operations if any fail", () => {
      const rawDb = new Database(dbPath);
      expect(() => {
        withTransaction(rawDb, () => {
          rawDb.prepare("INSERT INTO kv (key, value, updated_at) VALUES (?, ?, datetime('now'))").run("x", "1");
          // Force a constraint error: insert duplicate into a PRIMARY KEY column
          rawDb.prepare("INSERT INTO kv (key, value, updated_at) VALUES (?, ?, datetime('now'))").run("x", "2");
        });
      }).toThrow();

      // Neither row should exist since the transaction rolled back the first insert
      // Actually, the second INSERT would fail with UNIQUE constraint, but since kv uses
      // INSERT OR REPLACE normally, let's test with a different table
      rawDb.close();
    });

    it("rolls back all operations on error (turns table)", () => {
      const rawDb = new Database(dbPath);

      // Insert a turn to set up duplicate
      rawDb.prepare(
        `INSERT INTO turns (id, timestamp, state, thinking, tool_calls, token_usage, cost_cents)
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
      ).run("turn-existing", "2026-01-01T00:00:00Z", "running", "test", "[]", "{}", 0);

      expect(() => {
        withTransaction(rawDb, () => {
          // Insert a new valid turn
          rawDb.prepare(
            `INSERT INTO turns (id, timestamp, state, thinking, tool_calls, token_usage, cost_cents)
             VALUES (?, ?, ?, ?, ?, ?, ?)`,
          ).run("turn-new", "2026-01-01T00:00:01Z", "running", "test2", "[]", "{}", 0);
          // Insert duplicate — should fail
          rawDb.prepare(
            `INSERT INTO turns (id, timestamp, state, thinking, tool_calls, token_usage, cost_cents)
             VALUES (?, ?, ?, ?, ?, ?, ?)`,
          ).run("turn-existing", "2026-01-01T00:00:02Z", "running", "test3", "[]", "{}", 0);
        });
      }).toThrow();

      // "turn-new" should NOT exist due to rollback
      const row = rawDb.prepare("SELECT * FROM turns WHERE id = ?").get("turn-new");
      expect(row).toBeUndefined();
      rawDb.close();
    });
  });

  // ─── runTransaction on AutomatonDatabase ─────────────────────

  describe("runTransaction", () => {
    it("makes turn + tool calls atomic", () => {
      const turn: AgentTurn = {
        id: "turn-001",
        timestamp: new Date().toISOString(),
        state: "running",
        thinking: "Testing atomicity",
        toolCalls: [],
        tokenUsage: { promptTokens: 100, completionTokens: 50, totalTokens: 150 },
        costCents: 1,
      };

      const toolCall: ToolCallResult = {
        id: "tc-001",
        name: "exec",
        arguments: { command: "echo hi" },
        result: "hi",
        durationMs: 10,
      };

      db.runTransaction(() => {
        db.insertTurn(turn);
        db.insertToolCall(turn.id, toolCall);
      });

      const savedTurn = db.getTurnById("turn-001");
      expect(savedTurn).toBeDefined();
      expect(savedTurn!.thinking).toBe("Testing atomicity");

      const savedCalls = db.getToolCallsForTurn("turn-001");
      expect(savedCalls).toHaveLength(1);
      expect(savedCalls[0].name).toBe("exec");
    });

    it("rolls back turn if tool call insertion fails", () => {
      const turn: AgentTurn = {
        id: "turn-002",
        timestamp: new Date().toISOString(),
        state: "running",
        thinking: "Should be rolled back",
        toolCalls: [],
        tokenUsage: { promptTokens: 100, completionTokens: 50, totalTokens: 150 },
        costCents: 1,
      };

      // First insert a tool call to cause a duplicate
      db.runTransaction(() => {
        db.insertTurn({
          ...turn,
          id: "turn-setup",
          thinking: "setup",
        });
        db.insertToolCall("turn-setup", {
          id: "tc-dup",
          name: "exec",
          arguments: {},
          result: "ok",
          durationMs: 1,
        });
      });

      expect(() => {
        db.runTransaction(() => {
          db.insertTurn(turn);
          // This should fail because tc-dup already exists
          db.insertToolCall(turn.id, {
            id: "tc-dup",
            name: "exec",
            arguments: {},
            result: "fail",
            durationMs: 1,
          });
        });
      }).toThrow();

      // turn-002 should NOT exist due to rollback
      const savedTurn = db.getTurnById("turn-002");
      expect(savedTurn).toBeUndefined();
    });

    it("makes turn + tool calls + inbox ack atomic", () => {
      // Insert an inbox message
      db.insertInboxMessage({
        id: "msg-001",
        from: "0xsender",
        to: "0xme",
        content: "hello",
        signedAt: new Date().toISOString(),
        createdAt: new Date().toISOString(),
      });

      const unprocessed = db.getUnprocessedInboxMessages(10);
      expect(unprocessed).toHaveLength(1);

      const turn: AgentTurn = {
        id: "turn-003",
        timestamp: new Date().toISOString(),
        state: "running",
        thinking: "Processing message",
        toolCalls: [],
        tokenUsage: { promptTokens: 100, completionTokens: 50, totalTokens: 150 },
        costCents: 1,
      };

      db.runTransaction(() => {
        db.insertTurn(turn);
        db.markInboxMessageProcessed("msg-001");
      });

      const savedTurn = db.getTurnById("turn-003");
      expect(savedTurn).toBeDefined();

      const remaining = db.getUnprocessedInboxMessages(10);
      expect(remaining).toHaveLength(0);
    });
  });

  // ─── Schema creation in transaction ──────────────────────────

  describe("schema creation", () => {
    it("creates all expected tables", () => {
      const rawDb = new Database(dbPath);
      const tables = rawDb
        .prepare("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
        .all() as { name: string }[];
      const tableNames = tables.map((t) => t.name);

      expect(tableNames).toContain("turns");
      expect(tableNames).toContain("tool_calls");
      expect(tableNames).toContain("kv");
      expect(tableNames).toContain("schema_version");
      expect(tableNames).toContain("identity");
      expect(tableNames).toContain("heartbeat_entries");
      expect(tableNames).toContain("transactions");
      expect(tableNames).toContain("installed_tools");
      expect(tableNames).toContain("modifications");
      expect(tableNames).toContain("skills");
      expect(tableNames).toContain("children");
      expect(tableNames).toContain("registry");
      expect(tableNames).toContain("reputation");
      expect(tableNames).toContain("inbox_messages");
      rawDb.close();
    });
  });

  // ─── Migration v4 ────────────────────────────────────────────

  describe("migration v4", () => {
    it("creates policy_decisions and spend_tracking tables", () => {
      const rawDb = new Database(dbPath);
      const tables = rawDb
        .prepare("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
        .all() as { name: string }[];
      const tableNames = tables.map((t) => t.name);

      expect(tableNames).toContain("policy_decisions");
      expect(tableNames).toContain("spend_tracking");
      rawDb.close();
    });

    it("records schema version", () => {
      const rawDb = new Database(dbPath);
      const row = rawDb
        .prepare("SELECT MAX(version) as v FROM schema_version")
        .get() as { v: number };
      // Schema version should be the current SCHEMA_VERSION (updated by migrations)
      expect(row.v).toBeGreaterThanOrEqual(4);
      rawDb.close();
    });

    it("applies cleanly on a fresh database (simulates upgrade from v3)", () => {
      // The createDatabase() call in beforeEach already did this.
      // Just verify we can re-open the same DB without errors.
      db.close();
      const db2 = createDatabase(dbPath);
      expect(db2.getTurnCount()).toBe(0);
      db2.close();
      // Re-open for afterEach
      db = createDatabase(dbPath);
    });
  });

  // ─── deleteKVReturning (atomic wake_request) ─────────────────

  describe("deleteKVReturning", () => {
    it("returns value and deletes in one operation", () => {
      db.setKV("wake_request", "heartbeat_triggered");

      const value = db.deleteKVReturning("wake_request");
      expect(value).toBe("heartbeat_triggered");

      // Should be gone now
      const gone = db.getKV("wake_request");
      expect(gone).toBeUndefined();
    });

    it("returns undefined if key does not exist", () => {
      const value = db.deleteKVReturning("nonexistent");
      expect(value).toBeUndefined();
    });
  });

  // ─── WAL mode ────────────────────────────────────────────────

  describe("WAL mode", () => {
    it("database is in WAL mode", () => {
      const rawDb = new Database(dbPath);
      const result = rawDb.pragma("journal_mode") as { journal_mode: string }[];
      expect(result[0].journal_mode).toBe("wal");
      rawDb.close();
    });

    it("wal_autocheckpoint is set to 1000", () => {
      const rawDb = new Database(dbPath);
      const result = rawDb.pragma("wal_autocheckpoint") as { wal_autocheckpoint: number }[];
      expect(result[0].wal_autocheckpoint).toBe(1000);
      rawDb.close();
    });
  });

  // ─── checkpointWAL ──────────────────────────────────────────

  describe("checkpointWAL", () => {
    it("runs without error on a valid database", () => {
      const rawDb = new Database(dbPath);
      expect(() => checkpointWAL(rawDb)).not.toThrow();
      rawDb.close();
    });
  });

  // ─── Integrity check ────────────────────────────────────────

  describe("integrity check on startup", () => {
    it("passes on a healthy database", () => {
      // createDatabase() already ran without throwing, so integrity check passed.
      expect(db.getTurnCount()).toBe(0);
    });

    it("throws on a corrupt database", () => {
      db.close();

      // Corrupt the database file by overwriting part of it
      const data = fs.readFileSync(dbPath);
      const corrupted = Buffer.from(data);
      // Overwrite bytes in the middle of the file to corrupt it
      // (but keep the header so SQLite can open it)
      if (corrupted.length > 200) {
        for (let i = 100; i < 200; i++) {
          corrupted[i] = 0xFF;
        }
        fs.writeFileSync(dbPath, corrupted);

        // This may or may not throw depending on what we corrupted
        // At minimum, we verify createDatabase handles the integrity check
        try {
          const db2 = createDatabase(dbPath);
          // If it didn't throw, the corruption didn't affect the integrity check area
          db2.close();
        } catch (err: any) {
          expect(err.message).toMatch(/integrity|corrupt|malformed/i);
        }
      }

      // Re-create a clean DB for afterEach
      const cleanPath = makeTmpDbPath();
      dbPath = cleanPath;
      db = createDatabase(dbPath);
    });
  });
});

/**
 * Interactive Model Picker
 *
 * Presents a numbered list of available models and lets the user
 * pick one to set as the active inference model.
 *
 * Usage: automaton --pick-model
 */

import chalk from "chalk";
import { loadConfig, saveConfig, resolvePath } from "../config.js";
import { createDatabase } from "../state/database.js";
import { ModelRegistry } from "../inference/registry.js";
import { discoverOllamaModels } from "../ollama/discover.js";
import type { ModelEntry } from "../types.js";
import { promptOptional, closePrompts } from "./prompts.js";

const PROVIDER_LABEL: Record<string, string> = {
  openai: "OpenAI",
  anthropic: "Anthropic",
  conway: "Conway",
  ollama: "Ollama",
  other: "Other",
};

export async function runModelPicker(): Promise<void> {
  const config = loadConfig();
  if (!config) {
    console.log(chalk.red("  Automaton is not configured. Run: automaton --setup"));
    return;
  }

  const dbPath = resolvePath(config.dbPath);
  const db = createDatabase(dbPath);

  // Seed static baseline + discover Ollama models
  const registry = new ModelRegistry(db.raw);
  registry.initialize();

  const ollamaBaseUrl = process.env.OLLAMA_BASE_URL || config.ollamaBaseUrl;
  if (ollamaBaseUrl) {
    console.log(chalk.dim(`  Checking Ollama at ${ollamaBaseUrl}...`));
    await discoverOllamaModels(ollamaBaseUrl, db.raw);
  }

  const models = registry.getAll().filter((m) => m.enabled);

  if (models.length === 0) {
    console.log(chalk.yellow("  No models available in registry."));
    db.close();
    closePrompts();
    return;
  }

  console.log(chalk.cyan("\n  Available Models\n"));
  printModelTable(models, config.inferenceModel);

  console.log("");
  const input = await promptOptional("Enter model number (or press Enter to cancel)");
  closePrompts();

  if (!input) {
    console.log(chalk.dim("  Cancelled."));
    db.close();
    return;
  }

  const idx = parseInt(input, 10) - 1;
  if (isNaN(idx) || idx < 0 || idx >= models.length) {
    console.log(chalk.red(`  Invalid selection: "${input}"`));
    db.close();
    return;
  }

  const selected = models[idx];
  config.inferenceModel = selected.modelId;
  if (config.modelStrategy) {
    config.modelStrategy.inferenceModel = selected.modelId;
  }
  saveConfig(config);

  console.log(chalk.green(`\n  Active model set to: ${selected.modelId} (${selected.displayName})`));
  console.log(chalk.dim("  Restart the automaton for the change to take effect.\n"));

  db.close();
}

function printModelTable(models: ModelEntry[], currentModelId: string): void {
  const numWidth = String(models.length).length;

  for (let i = 0; i < models.length; i++) {
    const m = models[i];
    const num = String(i + 1).padStart(numWidth);
    const provider = (PROVIDER_LABEL[m.provider] || m.provider).padEnd(9);
    const cost = m.costPer1kInput === 0
      ? chalk.green("free     ")
      : chalk.dim(`$${(m.costPer1kInput / 100 / 1000 * 1_000_000).toFixed(2)}/M in`);
    const active = m.modelId === currentModelId ? chalk.green(" ◀ active") : "";
    const tools = m.supportsTools ? "" : chalk.dim(" (no tools)");

    console.log(
      `  ${chalk.white(num + ".")} ${chalk.cyan(m.modelId.padEnd(32))} ${chalk.dim(provider)} ${cost}${tools}${active}`,
    );
  }
}

/**
 * Authority Policy Rules
 *
 * Controls what actions are allowed based on input authority level.
 * External/heartbeat-initiated turns cannot use dangerous tools
 * or modify protected files.
 */

import type {
  PolicyRule,
  PolicyRequest,
  PolicyRuleResult,
} from "../../types.js";

/** Files protected from external-source self-modification */
const PROTECTED_PATHS = [
  "constitution.md",
  "SOUL.md",
  "automaton.json",
  "heartbeat.yml",
  "wallet.json",
  "config.json",
  "policy-engine",
  "policy-rules",
  "injection-defense",
  "self-mod/code",
  "audit-log",
] as const;

function deny(
  rule: string,
  reasonCode: string,
  humanMessage: string,
): PolicyRuleResult {
  return { rule, action: "deny", reasonCode, humanMessage };
}

/**
 * Check if an input source represents external (non-agent) authority.
 */
function isExternalSource(inputSource: string | undefined): boolean {
  return inputSource === undefined || inputSource === "heartbeat";
}

/**
 * Tools that must be blocked from external/heartbeat input sources.
 *
 * These are genuinely destructive or high-autonomy operations that should
 * only be initiated by the agent itself or its creator — never from
 * heartbeat tasks or untrusted external input.
 *
 * Tools NOT on this list (e.g., register_erc8004, give_feedback,
 * edit_own_file, transfer_credits) are allowed from any source because
 * they are core agent functionality already guarded by other policy rules
 * (financial limits, rate limits, path protection, etc.).
 */
const EXTERNAL_BLOCKED_TOOLS = [
  "delete_sandbox",
  "spawn_child",
  "fund_child",
  "update_genesis_prompt",
] as const;

/**
 * Deny specific high-risk tools when input comes from external sources.
 * Only agent-initiated or creator turns can use these tools.
 */
function createExternalToolRestrictionRule(): PolicyRule {
  return {
    id: "authority.external_tool_restriction",
    description: "Deny destructive/high-autonomy tools from external/heartbeat input sources",
    priority: 400,
    appliesTo: { by: "name", names: [...EXTERNAL_BLOCKED_TOOLS] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      if (isExternalSource(request.turnContext.inputSource)) {
        return deny(
          "authority.external_tool_restriction",
          "EXTERNAL_DANGEROUS_TOOL",
          `External input (source: ${request.turnContext.inputSource ?? "undefined"}) cannot use dangerous tool "${request.tool.name}"`,
        );
      }
      return null;
    },
  };
}

/**
 * Deny self-modification from external sources targeting protected paths.
 */
function createSelfModFromExternalRule(): PolicyRule {
  return {
    id: "authority.self_mod_from_external",
    description: "Deny edit_own_file/write_file targeting protected paths from external input",
    priority: 400,
    appliesTo: { by: "name", names: ["edit_own_file", "write_file"] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      if (!isExternalSource(request.turnContext.inputSource)) {
        return null;
      }

      const filePath = request.args.path as string | undefined;
      if (!filePath) return null;

      const normalizedPath = filePath.toLowerCase();
      for (const protectedPath of PROTECTED_PATHS) {
        if (
          normalizedPath.includes(protectedPath.toLowerCase())
        ) {
          return deny(
            "authority.self_mod_from_external",
            "EXTERNAL_SELF_MOD",
            `External input cannot modify protected path: "${filePath}" (matches "${protectedPath}")`,
          );
        }
      }

      return null;
    },
  };
}

/**
 * Create all authority policy rules.
 */
export function createAuthorityRules(): PolicyRule[] {
  return [
    createExternalToolRestrictionRule(),
    createSelfModFromExternalRule(),
  ];
}

/**
 * Financial Policy Rules
 *
 * Enforces spend limits, domain allowlists, and transfer caps
 * to prevent iterative credit drain and unauthorized payments.
 */

import type {
  PolicyRule,
  PolicyRequest,
  PolicyRuleResult,
  TreasuryPolicy,
} from "../../types.js";

function deny(
  rule: string,
  reasonCode: string,
  humanMessage: string,
): PolicyRuleResult {
  return { rule, action: "deny", reasonCode, humanMessage };
}

/**
 * Deny x402 payments above the configured per-payment max.
 */
function createX402MaxSingleRule(policy: TreasuryPolicy): PolicyRule {
  return {
    id: "financial.x402_max_single",
    description: `Deny x402 payments above ${policy.maxX402PaymentCents} cents`,
    priority: 500,
    appliesTo: { by: "name", names: ["x402_fetch"] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      // The amount is checked pre-payment in x402Fetch itself,
      // but we also enforce via policy for the declared max.
      // x402 payment amounts aren't in tool args — they come from the server.
      // This rule serves as a policy declaration; actual enforcement
      // happens in x402Fetch when maxPaymentCents is injected.
      return null;
    },
  };
}

/**
 * Deny x402 requests to domains not in the allowlist.
 */
function createX402DomainAllowlistRule(policy: TreasuryPolicy): PolicyRule {
  return {
    id: "financial.x402_domain_allowlist",
    description: "Deny x402 to domains not in allowlist",
    priority: 500,
    appliesTo: { by: "name", names: ["x402_fetch"] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const url = request.args.url as string | undefined;
      if (!url) return null;

      const allowedDomains = policy.x402AllowedDomains;
      if (allowedDomains.length === 0) {
        return deny(
          "financial.x402_domain_allowlist",
          "DOMAIN_NOT_ALLOWED",
          "x402 payments are disabled (empty allowlist)",
        );
      }

      let hostname: string;
      try {
        hostname = new URL(url).hostname;
      } catch {
        return deny(
          "financial.x402_domain_allowlist",
          "DOMAIN_NOT_ALLOWED",
          `Invalid URL: ${url}`,
        );
      }

      const isAllowed = allowedDomains.some(
        (domain) =>
          hostname === domain || hostname.endsWith(`.${domain}`),
      );

      if (!isAllowed) {
        return deny(
          "financial.x402_domain_allowlist",
          "DOMAIN_NOT_ALLOWED",
          `Domain "${hostname}" not in x402 allowlist: [${allowedDomains.join(", ")}]`,
        );
      }

      return null;
    },
  };
}

/**
 * Deny single transfers above the configured max.
 */
function createTransferMaxSingleRule(policy: TreasuryPolicy): PolicyRule {
  return {
    id: "financial.transfer_max_single",
    description: `Deny transfers above ${policy.maxSingleTransferCents} cents`,
    priority: 500,
    appliesTo: { by: "name", names: ["transfer_credits"] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const amount = request.args.amount_cents as number | undefined;
      if (amount === undefined) return null;

      if (amount > policy.maxSingleTransferCents) {
        return deny(
          "financial.transfer_max_single",
          "SPEND_LIMIT_EXCEEDED",
          `Transfer of ${amount} cents exceeds single transfer max of ${policy.maxSingleTransferCents} cents ($${(policy.maxSingleTransferCents / 100).toFixed(2)})`,
        );
      }

      return null;
    },
  };
}

/**
 * Deny if hourly transfer total would exceed cap.
 */
function createTransferHourlyCapRule(policy: TreasuryPolicy): PolicyRule {
  return {
    id: "financial.transfer_hourly_cap",
    description: `Deny if hourly transfers exceed ${policy.maxHourlyTransferCents} cents`,
    priority: 500,
    appliesTo: { by: "name", names: ["transfer_credits"] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const amount = request.args.amount_cents as number | undefined;
      if (amount === undefined) return null;

      const spendTracker = request.turnContext.sessionSpend;
      const check = spendTracker.checkLimit(amount, "transfer", policy);

      if (!check.allowed && check.reason?.includes("Hourly")) {
        return deny(
          "financial.transfer_hourly_cap",
          "SPEND_LIMIT_EXCEEDED",
          `Transfer would exceed hourly cap: current ${check.currentHourlySpend} + ${amount} > ${check.limitHourly} cents ($${(check.limitHourly / 100).toFixed(2)}/hr)`,
        );
      }

      return null;
    },
  };
}

/**
 * Deny if daily transfer total would exceed cap.
 */
function createTransferDailyCapRule(policy: TreasuryPolicy): PolicyRule {
  return {
    id: "financial.transfer_daily_cap",
    description: `Deny if daily transfers exceed ${policy.maxDailyTransferCents} cents`,
    priority: 500,
    appliesTo: { by: "name", names: ["transfer_credits"] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const amount = request.args.amount_cents as number | undefined;
      if (amount === undefined) return null;

      const spendTracker = request.turnContext.sessionSpend;
      const check = spendTracker.checkLimit(amount, "transfer", policy);

      if (!check.allowed && check.reason?.includes("Daily")) {
        return deny(
          "financial.transfer_daily_cap",
          "SPEND_LIMIT_EXCEEDED",
          `Transfer would exceed daily cap: current ${check.currentDailySpend} + ${amount} > ${check.limitDaily} cents ($${(check.limitDaily / 100).toFixed(2)}/day)`,
        );
      }

      return null;
    },
  };
}

/**
 * Deny any financial operation that would bring balance below minimum reserve.
 */
function createMinimumReserveRule(policy: TreasuryPolicy): PolicyRule {
  return {
    id: "financial.minimum_reserve",
    description: `Deny if balance would drop below ${policy.minimumReserveCents} cents reserve`,
    priority: 500,
    appliesTo: {
      by: "name",
      names: ["transfer_credits", "x402_fetch", "fund_child"],
    },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      // For transfer_credits and fund_child, we can check from args
      const amount = request.args.amount_cents as number | undefined;
      if (amount === undefined) return null;

      // We need the current balance from context
      // The balance check is done inside the tool execute function,
      // but we can check spend tracker totals as an additional guard
      const spendTracker = request.turnContext.sessionSpend;
      const hourlySpend = spendTracker.getHourlySpend("transfer");
      const dailySpend = spendTracker.getDailySpend("transfer");

      // This rule is a declaration — actual balance checking
      // requires the async getCreditsBalance call which happens
      // inside the tool execution. The tool itself has a guard
      // (cannot transfer more than half balance).
      return null;
    },
  };
}

/**
 * Deny if too many transfer operations in a single turn.
 * Prevents iterative credit drain within one turn.
 */
function createTurnTransferLimitRule(policy: TreasuryPolicy): PolicyRule {
  return {
    id: "financial.turn_transfer_limit",
    description: `Deny more than ${policy.maxTransfersPerTurn} transfers per turn`,
    priority: 500,
    appliesTo: { by: "name", names: ["transfer_credits"] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const count = request.turnContext.turnToolCallCount;

      if (count >= policy.maxTransfersPerTurn) {
        return deny(
          "financial.turn_transfer_limit",
          "TURN_TRANSFER_LIMIT",
          `Maximum ${policy.maxTransfersPerTurn} transfers per turn exceeded (current: ${count})`,
        );
      }

      return null;
    },
  };
}

/**
 * Deny inference calls if daily inference cost exceeds maxInferenceDailyCents.
 * Checks spend_tracking table for category 'inference'.
 */
function createInferenceDailyCapRule(policy: TreasuryPolicy): PolicyRule {
  return {
    id: "financial.inference_daily_cap",
    description: `Deny inference if daily cost exceeds ${policy.maxInferenceDailyCents} cents`,
    priority: 500,
    appliesTo: { by: "category", categories: ["conway"] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      // Only apply to inference-related tools
      if (request.tool.name !== "chat" && request.tool.name !== "inference") {
        return null;
      }

      const spendTracker = request.turnContext.sessionSpend;
      const dailyInferenceSpend = spendTracker.getDailySpend("inference");

      if (dailyInferenceSpend >= policy.maxInferenceDailyCents) {
        return deny(
          "financial.inference_daily_cap",
          "INFERENCE_BUDGET_EXCEEDED",
          `Daily inference budget exceeded: ${dailyInferenceSpend} cents spent (max ${policy.maxInferenceDailyCents} cents / $${(policy.maxInferenceDailyCents / 100).toFixed(2)}/day)`,
        );
      }

      return null;
    },
  };
}

/**
 * Return 'quarantine' (not deny) for transfer amounts above
 * requireConfirmationAboveCents. This is a soft limit requiring confirmation.
 */
function createRequireConfirmationRule(policy: TreasuryPolicy): PolicyRule {
  return {
    id: "financial.require_confirmation",
    description: `Quarantine transfers above ${policy.requireConfirmationAboveCents} cents for confirmation`,
    priority: 500,
    appliesTo: { by: "name", names: ["transfer_credits"] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const amount = request.args.amount_cents as number | undefined;
      if (amount === undefined) return null;

      if (amount > policy.requireConfirmationAboveCents) {
        return {
          rule: "financial.require_confirmation",
          action: "quarantine",
          reasonCode: "CONFIRMATION_REQUIRED",
          humanMessage: `Transfer of ${amount} cents ($${(amount / 100).toFixed(2)}) exceeds confirmation threshold of ${policy.requireConfirmationAboveCents} cents ($${(policy.requireConfirmationAboveCents / 100).toFixed(2)})`,
        };
      }

      return null;
    },
  };
}

/**
 * Create all financial policy rules.
 */
export function createFinancialRules(
  treasuryPolicy: TreasuryPolicy,
): PolicyRule[] {
  return [
    createX402MaxSingleRule(treasuryPolicy),
    createX402DomainAllowlistRule(treasuryPolicy),
    createTransferMaxSingleRule(treasuryPolicy),
    createTransferHourlyCapRule(treasuryPolicy),
    createTransferDailyCapRule(treasuryPolicy),
    createMinimumReserveRule(treasuryPolicy),
    createTurnTransferLimitRule(treasuryPolicy),
    createInferenceDailyCapRule(treasuryPolicy),
    createRequireConfirmationRule(treasuryPolicy),
  ];
}

