  it("classifies all expected dangerous tools correctly", () => {
    for (const [name, expectedLevel] of Object.entries(EXPECTED_RISK_LEVELS)) {
      if (expectedLevel !== "dangerous") continue;
      const tool = tools.find((t) => t.name === name);
