import type BetterSqlite3 from "better-sqlite3";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  assignTask,
  completeTask,
  createGoal,
  decomposeGoal,
  failTask,
  getGoalProgress,
  getReadyTasks,
  type TaskNode,
  type TaskResult,
} from "../../orchestration/task-graph.js";
import { getGoalById, getTaskById, getTasksByGoal } from "../../state/database.js";
import { createInMemoryDb } from "../orchestration/test-db.js";

const SUCCESS_RESULT: TaskResult = {
  success: true,
  output: "ok",
  artifacts: [],
  costCents: 10,
  duration: 100,
};

type DecomposeInput = Omit<TaskNode, "id" | "metadata">;

function makeTask(goalId: string, title: string, overrides: Partial<DecomposeInput> = {}): DecomposeInput {
  return {
    parentId: null,
    goalId,
    title,
    description: `${title} desc`,
    status: "pending",
    assignedTo: null,
    agentRole: "generalist",
    priority: 50,
    dependencies: [],
    result: null,
    ...overrides,
  };
}

describe("integration/multi-agent-coordination", () => {
  let db: BetterSqlite3.Database;

  beforeEach(() => {
    db = createInMemoryDb();
  });

  afterEach(() => {
    db.close();
  });

  // ---------------------------------------------------------------------------
  // 1. Parent assigns tasks to multiple children
  // ---------------------------------------------------------------------------

  describe("parent assigns tasks to multiple children", () => {
    it("decomposes goal into 3 parallel tasks that are all pending", () => {
      const goal = createGoal(db, "Multi-agent goal", "Run 3 tasks in parallel");

      decomposeGoal(db, goal.id, [
        makeTask(goal.id, "Task Alpha"),
        makeTask(goal.id, "Task Beta"),
        makeTask(goal.id, "Task Gamma"),
      ]);

      const tasks = getTasksByGoal(db, goal.id);
      expect(tasks).toHaveLength(3);
      for (const task of tasks) {
        expect(task.status).toBe("pending");
        expect(task.dependencies).toEqual([]);
      }
    });

    it("all 3 parallel tasks appear in getReadyTasks", () => {
      const goal = createGoal(db, "Parallel goal", "All tasks ready immediately");

      decomposeGoal(db, goal.id, [
        makeTask(goal.id, "Task Alpha"),
        makeTask(goal.id, "Task Beta"),
        makeTask(goal.id, "Task Gamma"),
      ]);

      const readyTitles = getReadyTasks(db)
        .filter((t) => t.goalId === goal.id)
        .map((t) => t.title);

      expect(readyTitles).toContain("Task Alpha");
      expect(readyTitles).toContain("Task Beta");
      expect(readyTitles).toContain("Task Gamma");
    });

    it("assigning each task to a different agent sets status to assigned", () => {
      const goal = createGoal(db, "Assignment goal", "Each task gets its own agent");

      decomposeGoal(db, goal.id, [
        makeTask(goal.id, "Task Alpha"),
        makeTask(goal.id, "Task Beta"),
        makeTask(goal.id, "Task Gamma"),
      ]);

      const tasks = getTasksByGoal(db, goal.id);
      const agents = ["0xagent1", "0xagent2", "0xagent3"];

      for (let i = 0; i < tasks.length; i++) {
        assignTask(db, tasks[i].id, agents[i]);
      }

      const updated = getTasksByGoal(db, goal.id);
      const assignedAgents = updated.map((t) => t.assignedTo).sort();
      expect(assignedAgents).toEqual(["0xagent1", "0xagent2", "0xagent3"].sort());
      for (const task of updated) {
        expect(task.status).toBe("assigned");
      }
    });
  });

  // ---------------------------------------------------------------------------
  // 2. Task results collected via messaging
  // ---------------------------------------------------------------------------

  describe("task results collected via messaging", () => {
    it("completing each assigned task writes the result to that task", () => {
      const goal = createGoal(db, "Result collection goal", "Collect results from 3 agents");

      decomposeGoal(db, goal.id, [
        makeTask(goal.id, "Task Alpha"),
        makeTask(goal.id, "Task Beta"),
        makeTask(goal.id, "Task Gamma"),
      ]);

      const tasks = getTasksByGoal(db, goal.id);
      for (const task of tasks) {
        completeTask(db, task.id, SUCCESS_RESULT);
      }

      const completed = getTasksByGoal(db, goal.id);
      for (const task of completed) {
        expect(task.status).toBe("completed");
        expect(task.result).toMatchObject({ success: true, output: "ok" });
      }
    });

    it("goal status becomes completed after all tasks complete", () => {
      const goal = createGoal(db, "Completion goal", "Goal finishes when all tasks done");

      decomposeGoal(db, goal.id, [
        makeTask(goal.id, "Task Alpha"),
        makeTask(goal.id, "Task Beta"),
        makeTask(goal.id, "Task Gamma"),
      ]);

      const tasks = getTasksByGoal(db, goal.id);

      // Goal should still be active while tasks are in progress
      expect(getGoalById(db, goal.id)?.status).toBe("active");

      for (const task of tasks) {
        completeTask(db, task.id, SUCCESS_RESULT);
      }

      expect(getGoalById(db, goal.id)?.status).toBe("completed");
    });

    it("getGoalProgress shows total=3 completed=3 after all tasks finish", () => {
      const goal = createGoal(db, "Progress goal", "Track progress across 3 tasks");

      decomposeGoal(db, goal.id, [
        makeTask(goal.id, "Task Alpha"),
        makeTask(goal.id, "Task Beta"),
        makeTask(goal.id, "Task Gamma"),
      ]);

      const tasks = getTasksByGoal(db, goal.id);
      for (const task of tasks) {
        completeTask(db, task.id, SUCCESS_RESULT);
      }

      const progress = getGoalProgress(db, goal.id);
      expect(progress.total).toBe(3);
      expect(progress.completed).toBe(3);
      expect(progress.failed).toBe(0);
      expect(progress.blocked).toBe(0);
    });
  });

  // ---------------------------------------------------------------------------
  // 3. Dependency chain: A → B → C
  // ---------------------------------------------------------------------------

  describe("dependency chain: A completes → B unblocks → B assigned", () => {
    it("initially only Task A is pending; B and C are blocked", () => {
      const goal = createGoal(db, "Chain goal", "Linear dependency chain");

      decomposeGoal(db, goal.id, [
        makeTask(goal.id, "Task A"),
        makeTask(goal.id, "Task B", { dependencies: ["Task A"] }),
        makeTask(goal.id, "Task C", { dependencies: ["Task B"] }),
      ]);

      const tasks = getTasksByGoal(db, goal.id);
      const taskA = tasks.find((t) => t.title === "Task A")!;
      const taskB = tasks.find((t) => t.title === "Task B")!;
      const taskC = tasks.find((t) => t.title === "Task C")!;

      expect(taskA.status).toBe("pending");
      expect(taskB.status).toBe("blocked");
      expect(taskC.status).toBe("blocked");
    });

    it("completing Task A unblocks Task B (B becomes pending)", () => {
      const goal = createGoal(db, "Chain goal", "Linear dependency chain");

      decomposeGoal(db, goal.id, [
        makeTask(goal.id, "Task A"),
        makeTask(goal.id, "Task B", { dependencies: ["Task A"] }),
        makeTask(goal.id, "Task C", { dependencies: ["Task B"] }),
      ]);

      const tasks = getTasksByGoal(db, goal.id);
      const taskA = tasks.find((t) => t.title === "Task A")!;

      completeTask(db, taskA.id, SUCCESS_RESULT);

      const afterA = getTasksByGoal(db, goal.id);
      const taskB = afterA.find((t) => t.title === "Task B")!;
      const taskC = afterA.find((t) => t.title === "Task C")!;

      expect(taskB.status).toBe("pending");
      expect(taskC.status).toBe("blocked");
    });

    it("completing Task B unblocks Task C (C becomes pending)", () => {
      const goal = createGoal(db, "Chain goal", "Linear dependency chain");

      decomposeGoal(db, goal.id, [
        makeTask(goal.id, "Task A"),
        makeTask(goal.id, "Task B", { dependencies: ["Task A"] }),
        makeTask(goal.id, "Task C", { dependencies: ["Task B"] }),
      ]);

      const tasks = getTasksByGoal(db, goal.id);
      const taskA = tasks.find((t) => t.title === "Task A")!;
      completeTask(db, taskA.id, SUCCESS_RESULT);

      const afterA = getTasksByGoal(db, goal.id);
      const taskB = afterA.find((t) => t.title === "Task B")!;
      completeTask(db, taskB.id, SUCCESS_RESULT);

      const afterB = getTasksByGoal(db, goal.id);
      const taskC = afterB.find((t) => t.title === "Task C")!;
      expect(taskC.status).toBe("pending");
    });

    it("completing Task C marks the goal as completed", () => {
      const goal = createGoal(db, "Chain goal", "Linear dependency chain");

      decomposeGoal(db, goal.id, [
        makeTask(goal.id, "Task A"),
        makeTask(goal.id, "Task B", { dependencies: ["Task A"] }),
        makeTask(goal.id, "Task C", { dependencies: ["Task B"] }),
      ]);

      const tasks = getTasksByGoal(db, goal.id);
      const taskA = tasks.find((t) => t.title === "Task A")!;
      completeTask(db, taskA.id, SUCCESS_RESULT);

      const afterA = getTasksByGoal(db, goal.id);
      const taskB = afterA.find((t) => t.title === "Task B")!;
      completeTask(db, taskB.id, SUCCESS_RESULT);

      const afterB = getTasksByGoal(db, goal.id);
      const taskC = afterB.find((t) => t.title === "Task C")!;
      completeTask(db, taskC.id, SUCCESS_RESULT);

      expect(getGoalById(db, goal.id)?.status).toBe("completed");
    });
  });

  // ---------------------------------------------------------------------------
  // 4. Failure propagation
  // ---------------------------------------------------------------------------

  describe("failure propagation", () => {
    it("failing Task A permanently keeps Task B blocked", () => {
      const goal = createGoal(db, "Failure goal", "Propagate failure downstream");

      decomposeGoal(db, goal.id, [
        makeTask(goal.id, "Task A"),
        makeTask(goal.id, "Task B", { dependencies: ["Task A"] }),
      ]);

      const tasks = getTasksByGoal(db, goal.id);
      const taskA = tasks.find((t) => t.title === "Task A")!;

      failTask(db, taskA.id, "fatal error", false);

      const taskB = getTasksByGoal(db, goal.id).find((t) => t.title === "Task B")!;
      expect(getTaskById(db, taskA.id)?.status).toBe("failed");
      expect(taskB.status).toBe("blocked");
    });

    it("failing a task with retries remaining resets it back to pending", () => {
      const goal = createGoal(db, "Retry goal", "Task retries on transient failure");

      decomposeGoal(db, goal.id, [
        makeTask(goal.id, "Task A"),
        makeTask(goal.id, "Task B"),
      ]);

      const tasks = getTasksByGoal(db, goal.id);
      const taskB = tasks.find((t) => t.title === "Task B")!;

      // Give the task retry budget by updating directly via db before failing
      db.prepare(
        "UPDATE task_graph SET max_retries = 2, retry_count = 0, status = 'running' WHERE id = ?",
      ).run(taskB.id);

      failTask(db, taskB.id, "transient error", true);

      const retried = getTaskById(db, taskB.id);
      expect(retried?.status).toBe("pending");
      expect(retried?.retryCount).toBe(1);
      expect(retried?.assignedTo).toBeNull();
    });
  });
});

import { describe, it, expect, beforeEach } from "vitest";
import {
  AgentContextAggregator,
  type AgentStatusUpdate,
} from "../../memory/agent-context-aggregator.js";

function makeUpdate(overrides: Partial<AgentStatusUpdate> = {}): AgentStatusUpdate {
  return {
    agentAddress: "0xagent1",
    department: "engineering",
    role: "generalist",
    status: "running",
    kind: "progress",
    message: "Working on task",
    ...overrides,
  };
}

describe("AgentContextAggregator", () => {
  let aggregator: AgentContextAggregator;

  beforeEach(() => {
    aggregator = new AgentContextAggregator();
  });

  // ---------------------------------------------------------------------------
  // triageUpdate
  // ---------------------------------------------------------------------------

  describe("triageUpdate", () => {
    it("returns full for update with error field", () => {
      const update = makeUpdate({ error: "something went wrong" });
      expect(aggregator.triageUpdate(update)).toBe("full");
    });

    it("returns full for status containing 'error'", () => {
      const update = makeUpdate({ status: "error", kind: "progress" });
      expect(aggregator.triageUpdate(update)).toBe("full");
    });

    it("returns full for status containing 'failed'", () => {
      const update = makeUpdate({ status: "failed", kind: "progress" });
      expect(aggregator.triageUpdate(update)).toBe("full");
    });

    it("returns full for kind 'exception'", () => {
      const update = makeUpdate({ status: "running", kind: "exception" });
      expect(aggregator.triageUpdate(update)).toBe("full");
    });

    it("returns full for large financial event (budgetImpactPercent > 10)", () => {
      const update = makeUpdate({ budgetImpactPercent: 15 });
      expect(aggregator.triageUpdate(update)).toBe("full");
    });

    it("returns full when financialAmount exceeds 10% of dailyBudget", () => {
      const update = makeUpdate({ financialAmount: 200, dailyBudget: 1000 });
      expect(aggregator.triageUpdate(update)).toBe("full");
    });

    it("returns full for blocked update (blocked: true)", () => {
      const update = makeUpdate({ blocked: true });
      expect(aggregator.triageUpdate(update)).toBe("full");
    });

    it("returns full for status 'blocked'", () => {
      const update = makeUpdate({ status: "blocked", kind: "progress" });
      expect(aggregator.triageUpdate(update)).toBe("full");
    });

    it("returns full for status 'stalled'", () => {
      const update = makeUpdate({ status: "stalled", kind: "progress" });
      expect(aggregator.triageUpdate(update)).toBe("full");
    });

    it("returns summary for completed tasks", () => {
      const update = makeUpdate({ status: "completed", kind: "done" });
      expect(aggregator.triageUpdate(update)).toBe("summary");
    });

    it("returns summary for progress/running status", () => {
      const update = makeUpdate({ status: "running", kind: "progress" });
      expect(aggregator.triageUpdate(update)).toBe("summary");
    });

    it("returns count for heartbeat status", () => {
      const update = makeUpdate({ status: "heartbeat", kind: "heartbeat" });
      expect(aggregator.triageUpdate(update)).toBe("count");
    });

    it("returns count for alive status", () => {
      const update = makeUpdate({ status: "alive", kind: "alive" });
      expect(aggregator.triageUpdate(update)).toBe("count");
    });

    it("returns count for ping kind", () => {
      const update = makeUpdate({ status: "ping", kind: "ping" });
      expect(aggregator.triageUpdate(update)).toBe("count");
    });
  });

  // ---------------------------------------------------------------------------
  // aggregateChildUpdates
  // ---------------------------------------------------------------------------

  describe("aggregateChildUpdates", () => {
    it("handles empty updates array", () => {
      const result = aggregator.aggregateChildUpdates([], 1000);
      expect(result.fullUpdates).toHaveLength(0);
      expect(result.summaryEntries).toHaveLength(0);
      expect(result.heartbeatCount).toBe(0);
      expect(result.triageCounts).toEqual({ full: 0, summary: 0, count: 0 });
    });

    it("puts error updates in fullUpdates", () => {
      const updates = [
        makeUpdate({ error: "disk full" }),
        makeUpdate({ status: "running" }),
      ];
      const result = aggregator.aggregateChildUpdates(updates, 1000);
      expect(result.fullUpdates).toHaveLength(1);
      expect(result.fullUpdates[0].error).toBe("disk full");
    });

    it("counts heartbeats separately", () => {
      const updates = [
        makeUpdate({ status: "heartbeat", kind: "heartbeat" }),
        makeUpdate({ status: "alive", kind: "alive" }),
        makeUpdate({ status: "running" }),
      ];
      const result = aggregator.aggregateChildUpdates(updates, 1000);
      expect(result.heartbeatCount).toBe(2);
    });

    it("groups summary updates by department", () => {
      const updates = [
        makeUpdate({ department: "engineering", status: "running" }),
        makeUpdate({ department: "engineering", status: "running" }),
        makeUpdate({ department: "design", status: "running" }),
      ];
      const result = aggregator.aggregateChildUpdates(updates, 1000);
      const groups = result.summaryEntries.map((e) => e.group);
      expect(groups).toContain("engineering");
      expect(groups).toContain("design");
      const engEntry = result.summaryEntries.find((e) => e.group === "engineering");
      expect(engEntry?.count).toBe(2);
      const designEntry = result.summaryEntries.find((e) => e.group === "design");
      expect(designEntry?.count).toBe(1);
    });

    it("groups by role when department is missing", () => {
      const updates = [
        makeUpdate({ department: undefined, role: "analyst", status: "running" }),
        makeUpdate({ department: undefined, role: "analyst", status: "running" }),
      ];
      const result = aggregator.aggregateChildUpdates(updates, 1000);
      const entry = result.summaryEntries.find((e) => e.group === "analyst");
      expect(entry).toBeDefined();
      expect(entry?.count).toBe(2);
    });

    it("returns correct triageCounts", () => {
      const updates = [
        makeUpdate({ error: "oh no" }),
        makeUpdate({ status: "running" }),
        makeUpdate({ status: "heartbeat", kind: "heartbeat" }),
      ];
      const result = aggregator.aggregateChildUpdates(updates, 1000);
      expect(result.triageCounts.full).toBe(1);
      expect(result.triageCounts.summary).toBe(1);
      expect(result.triageCounts.count).toBe(1);
    });

    it("preserves highlight messages in summary entries", () => {
      const updates = [
        makeUpdate({ department: "engineering", message: "Task X is in progress" }),
      ];
      const result = aggregator.aggregateChildUpdates(updates, 1000);
      const entry = result.summaryEntries.find((e) => e.group === "engineering");
      expect(entry?.highlight).toBe("Task X is in progress");
    });

    it("respects token budget and truncates when exceeded", () => {
      const updates = Array.from({ length: 50 }, (_, i) =>
        makeUpdate({
          agentAddress: `0xagent${i}`,
          department: `dept-${i % 5}`,
          message: `Long message about progress on task number ${i} with details`,
        }),
      );
      const result = aggregator.aggregateChildUpdates(updates, 10); // very small budget
      // rough check: summary should be <= 10 tokens * 4 chars/token + some overhead
      expect(result.summary.length).toBeLessThanOrEqual(10 * 4 + 50);
    });
  });
});

/**
 * Financial Policy Rules Tests
 *
 * Tests for all financial limit rules:
 * - x402_max_single denies payments > 100 cents
 * - x402_domain_allowlist denies non-conway.tech domains
 * - transfer_max_single denies transfers > 5000 cents
 * - transfer_hourly_cap denies when hourly total > 10000
 * - transfer_daily_cap denies when daily total > 25000
 * - minimum_reserve denies when balance would drop below 1000
 * - turn_transfer_limit denies > 2 transfers per turn
 * - Iterative drain scenario: 10 successive transfers blocked by hourly cap
 */

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import Database from "better-sqlite3";
import path from "path";
import os from "os";
import fs from "fs";
import { createFinancialRules } from "../agent/policy-rules/financial.js";
import { PolicyEngine } from "../agent/policy-engine.js";
import { SpendTracker } from "../agent/spend-tracker.js";
import type {
  AutomatonTool,
  PolicyRequest,
  PolicyRule,
  TreasuryPolicy,
  SpendTrackerInterface,
  SpendEntry,
  SpendCategory,
  LimitCheckResult,
  ToolContext,
} from "../types.js";
import { DEFAULT_TREASURY_POLICY } from "../types.js";

// ─── Test Helpers ───────────────────────────────────────────────

function createTestDb(): Database.Database {
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "financial-test-"));
  const dbPath = path.join(tmpDir, "test.db");
  const db = new Database(dbPath);
  db.pragma("journal_mode = WAL");

  db.exec(`
    CREATE TABLE IF NOT EXISTS schema_version (
      version INTEGER PRIMARY KEY,
      applied_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
    CREATE TABLE IF NOT EXISTS policy_decisions (
      id TEXT PRIMARY KEY,
      turn_id TEXT,
      tool_name TEXT NOT NULL,
      tool_args_hash TEXT NOT NULL,
      risk_level TEXT NOT NULL CHECK(risk_level IN ('safe','caution','dangerous','forbidden')),
      decision TEXT NOT NULL CHECK(decision IN ('allow','deny','quarantine')),
      rules_evaluated TEXT NOT NULL DEFAULT '[]',
      rules_triggered TEXT NOT NULL DEFAULT '[]',
      reason TEXT NOT NULL DEFAULT '',
      latency_ms INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
    CREATE TABLE IF NOT EXISTS spend_tracking (
      id TEXT PRIMARY KEY,
      tool_name TEXT NOT NULL,
      amount_cents INTEGER NOT NULL,
      recipient TEXT,
      domain TEXT,
      category TEXT NOT NULL CHECK(category IN ('transfer','x402','inference','other')),
      window_hour TEXT NOT NULL,
      window_day TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );
    CREATE INDEX IF NOT EXISTS idx_spend_hour ON spend_tracking(category, window_hour);
    CREATE INDEX IF NOT EXISTS idx_spend_day ON spend_tracking(category, window_day);
  `);

  return db;
}

