/**
 * Input Validation Policy Rules
 *
 * Validates tool arguments before execution. Catches malformed
 * input before it reaches any shell command or API call.
 */

import type { PolicyRule, PolicyRequest, PolicyRuleResult } from "../../types.js";

const PACKAGE_NAME_RE = /^[@a-zA-Z0-9._/-]+$/;
const SKILL_NAME_RE = /^[a-zA-Z0-9-]+$/;
const GIT_HASH_RE = /^[a-f0-9]{7,40}$/;
const ADDRESS_RE = /^0x[a-fA-F0-9]{40}$/;
const CRON_PARTS_RE = /^(\*|[\d,*/-]+)\s+(\*|[\d,*/-]+)\s+(\*|[\d,*/-]+)\s+(\*|[\d,*/-]+)\s+(\*|[\d,*/-]+)$/;

function deny(rule: string, reasonCode: string, humanMessage: string): PolicyRuleResult {
  return { rule, action: "deny", reasonCode, humanMessage };
}

/**
 * Validate npm package name format.
 */
function createPackageNameRule(): PolicyRule {
  return {
    id: "validate.package_name",
    description: "Validate npm package name format",
    priority: 100,
    appliesTo: {
      by: "name",
      names: ["install_npm_package", "install_mcp_server"],
    },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const pkg = request.args.package as string | undefined;
      if (pkg === undefined) return null;

      if (!PACKAGE_NAME_RE.test(pkg)) {
        return deny(
          "validate.package_name",
          "VALIDATION_FAILED",
          `Invalid package name: "${pkg}". Must match ${PACKAGE_NAME_RE.source}`,
        );
      }
      return null;
    },
  };
}

/**
 * Validate skill name format.
 */
function createSkillNameRule(): PolicyRule {
  return {
    id: "validate.skill_name",
    description: "Validate skill name format (alphanumeric + hyphens only)",
    priority: 100,
    appliesTo: {
      by: "name",
      names: ["install_skill", "create_skill", "remove_skill"],
    },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const name = request.args.name as string | undefined;
      if (name === undefined) return null;

      if (!SKILL_NAME_RE.test(name)) {
        return deny(
          "validate.skill_name",
          "VALIDATION_FAILED",
          `Invalid skill name: "${name}". Must match ${SKILL_NAME_RE.source}`,
        );
      }
      return null;
    },
  };
}

/**
 * Validate git commit hash format.
 */
function createGitHashRule(): PolicyRule {
  return {
    id: "validate.git_hash",
    description: "Validate git commit hash format",
    priority: 100,
    appliesTo: {
      by: "name",
      names: ["pull_upstream"],
    },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const commit = request.args.commit as string | undefined;
      if (commit === undefined) return null; // commit is optional

      if (!GIT_HASH_RE.test(commit)) {
        return deny(
          "validate.git_hash",
          "VALIDATION_FAILED",
          `Invalid git hash: "${commit}". Must be 7-40 lowercase hex characters.`,
        );
      }
      return null;
    },
  };
}

/**
 * Validate port number range.
 */
function createPortRangeRule(): PolicyRule {
  return {
    id: "validate.port_range",
    description: "Validate port number is in valid range (1-65535)",
    priority: 100,
    appliesTo: {
      by: "name",
      names: ["expose_port", "remove_port"],
    },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const port = request.args.port as number | undefined;
      if (port === undefined) return null;

      if (!Number.isInteger(port) || port < 1 || port > 65535) {
        return deny(
          "validate.port_range",
          "VALIDATION_FAILED",
          `Invalid port: ${port}. Must be integer 1-65535.`,
        );
      }
      return null;
    },
  };
}

/**
 * Validate cron expression structure.
 */
function createCronExpressionRule(): PolicyRule {
  return {
    id: "validate.cron_expression",
    description: "Validate cron expression format",
    priority: 100,
    appliesTo: {
      by: "name",
      names: ["modify_heartbeat"],
    },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const schedule = request.args.schedule as string | undefined;
      if (schedule === undefined) return null;

      if (!CRON_PARTS_RE.test(schedule.trim())) {
        return deny(
          "validate.cron_expression",
          "VALIDATION_FAILED",
          `Invalid cron expression: "${schedule}". Must be 5 space-separated fields.`,
        );
      }
      return null;
    },
  };
}

/**
 * Validate Ethereum address format.
 */
function createAddressFormatRule(): PolicyRule {
  return {
    id: "validate.address_format",
    description: "Validate Ethereum address format (0x + 40 hex chars)",
    priority: 100,
    appliesTo: {
      by: "name",
      names: ["transfer_credits", "send_message", "fund_child"],
    },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const address = (request.args.to_address as string | undefined)
        ?? (request.args.agent_address as string | undefined);
      if (address === undefined) return null;

      if (!ADDRESS_RE.test(address)) {
        return deny(
          "validate.address_format",
          "VALIDATION_FAILED",
          `Invalid address format: "${address}". Must be 0x followed by 40 hex characters.`,
        );
      }
      return null;
    },
  };
}

export function createValidationRules(): PolicyRule[] {
  return [
    createPackageNameRule(),
    createSkillNameRule(),
    createGitHashRule(),
    createPortRangeRule(),
    createCronExpressionRule(),
    createAddressFormatRule(),
  ];
}

/**
 * Rate Limit Policy Rules
 *
 * Enforces rate limits on sensitive operations to prevent abuse.
 * Queries the policy_decisions table to count recent operations.
 */

import type {
  PolicyRule,
  PolicyRequest,
  PolicyRuleResult,
} from "../../types.js";

function deny(
  rule: string,
  reasonCode: string,
  humanMessage: string,
): PolicyRuleResult {
  return { rule, action: "deny", reasonCode, humanMessage };
}

/**
 * Count recent policy decisions for a tool within a time window.
 * Uses the policy_decisions table which logs all tool evaluations.
 */
function countRecentDecisions(
  db: import("better-sqlite3").Database,
  toolName: string,
  windowMs: number,
): number {
  const cutoff = new Date(Date.now() - windowMs);
  // SQLite datetime format: 'YYYY-MM-DD HH:MM:SS'
  const cutoffStr = cutoff.toISOString().replace("T", " ").replace(/\.\d{3}Z$/, "");
  const row = db
    .prepare(
      `SELECT COUNT(*) as count FROM policy_decisions
       WHERE tool_name = ? AND decision = 'allow' AND created_at >= ?`,
    )
    .get(toolName, cutoffStr) as { count: number };
  return row.count;
}

/**
 * Maximum 1 genesis prompt change per day.
 */
function createGenesisPromptDailyRule(): PolicyRule {
  return {
    id: "rate.genesis_prompt_daily",
    description: "Maximum 1 update_genesis_prompt per day",
    priority: 600,
    appliesTo: { by: "name", names: ["update_genesis_prompt"] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      // Access the raw database through the tool context
      // The db is available via context.db, but we need the raw sqlite instance
      // Rate limit rules need the raw DB to query policy_decisions
      const db = (request.context.db as any)?.raw ?? (request.context as any).rawDb;
      if (!db) return deny(this.id, "DB_UNAVAILABLE", "Rate limit check failed: database not accessible");

      const oneDayMs = 24 * 60 * 60 * 1000;
      const recentCount = countRecentDecisions(db, "update_genesis_prompt", oneDayMs);

      if (recentCount >= 1) {
        return deny(
          "rate.genesis_prompt_daily",
          "RATE_LIMIT_GENESIS",
          `Genesis prompt change rate exceeded: ${recentCount} changes in the last 24 hours (max 1/day)`,
        );
      }

      return null;
    },
  };
}

/**
 * Maximum 10 self-mod operations per hour.
 */
function createSelfModHourlyRule(): PolicyRule {
  return {
    id: "rate.self_mod_hourly",
    description: "Maximum 10 edit_own_file calls per hour",
    priority: 600,
    appliesTo: { by: "name", names: ["edit_own_file"] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const db = (request.context.db as any)?.raw ?? (request.context as any).rawDb;
      if (!db) return deny(this.id, "DB_UNAVAILABLE", "Rate limit check failed: database not accessible");

      const oneHourMs = 60 * 60 * 1000;
      const recentCount = countRecentDecisions(db, "edit_own_file", oneHourMs);

      if (recentCount >= 10) {
        return deny(
          "rate.self_mod_hourly",
          "RATE_LIMIT_SELF_MOD",
          `Self-modification rate exceeded: ${recentCount} edits in the last hour (max 10/hour)`,
        );
      }

      return null;
    },
  };
}

/**
 * Maximum 3 child spawns per day.
 */
function createSpawnDailyRule(): PolicyRule {
  return {
    id: "rate.spawn_daily",
    description: "Maximum 3 spawn_child calls per day",
    priority: 600,
    appliesTo: { by: "name", names: ["spawn_child"] },
    evaluate(request: PolicyRequest): PolicyRuleResult | null {
      const db = (request.context.db as any)?.raw ?? (request.context as any).rawDb;
      if (!db) return deny(this.id, "DB_UNAVAILABLE", "Rate limit check failed: database not accessible");

      const oneDayMs = 24 * 60 * 60 * 1000;
      const recentCount = countRecentDecisions(db, "spawn_child", oneDayMs);

      if (recentCount >= 3) {
        return deny(
          "rate.spawn_daily",
          "RATE_LIMIT_SPAWN",
          `Child spawn rate exceeded: ${recentCount} spawns in the last 24 hours (max 3/day)`,
        );
      }

      return null;
    },
  };
}

/**
 * Create all rate limit policy rules.
 */
export function createRateLimitRules(): PolicyRule[] {
  return [
    createGenesisPromptDailyRule(),
    createSelfModHourlyRule(),
    createSpawnDailyRule(),
  ];
}

/**
 * Message Validation
 *
 * Validates social messages for size limits, replay protection,
 * and address format.
 *
 * Phase 3.2: Social & Registry Hardening
 */

import type { MessageValidationResult } from "../types.js";
import { MESSAGE_LIMITS } from "./signing.js";

/**
 * Validate a social message for size, timestamp, and address constraints.
 */
export function validateMessage(message: {
  from: string;
  to: string;
  content: string;
  signed_at?: string;
  timestamp?: string;
}): MessageValidationResult {
  const errors: string[] = [];

  // Size limits
  const totalSize = JSON.stringify(message).length;
  if (totalSize > MESSAGE_LIMITS.maxTotalSize) {
    errors.push(`Message exceeds total size limit: ${totalSize} > ${MESSAGE_LIMITS.maxTotalSize}`);
  }
  if (message.content.length > MESSAGE_LIMITS.maxContentLength) {
    errors.push(`Content exceeds size limit: ${message.content.length} > ${MESSAGE_LIMITS.maxContentLength}`);
  }

  // Timestamp validation (replay protection)
  const ts = message.signed_at || message.timestamp;
  if (ts) {
    const parsed = new Date(ts).getTime();
    if (isNaN(parsed)) {
      errors.push("Invalid timestamp");
    } else {
      const age = Date.now() - parsed;
      if (age > MESSAGE_LIMITS.replayWindowMs) {
        errors.push("Message too old (possible replay)");
      }
      if (age < -60_000) {
        errors.push("Message from future");
      }
    }
  }

  // Address validation
  if (!isValidAddress(message.from)) {
    errors.push("Invalid sender address");
  }
  if (!isValidAddress(message.to)) {
    errors.push("Invalid recipient address");
  }

  return { valid: errors.length === 0, errors };
}

/**
 * Validate that a relay URL uses HTTPS.
 * Throws if the URL is not HTTPS.
 */
export function validateRelayUrl(url: string): void {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    throw new Error(`Invalid relay URL: ${url}`);
  }
  if (parsed.protocol !== "https:") {
    throw new Error(`Relay URL must use HTTPS: ${url}`);
  }
}

/**
 * Check if a string is a valid Ethereum-style hex address.
 */
export function isValidAddress(address: string): boolean {
  return /^0x[0-9a-fA-F]{40}$/.test(address);
}

